/// <summary>
/// Service class for CSD transfer orders creation.
/// </summary>
class METCreateCSDTransferOrderService extends SysOperationServiceBase
{
    METCreateCSDTransferOrderContract  contract;
    Map                                profileSalesLine;
    container                          csdSalesOrderList;
    InventLocationId                   csdWarehouse;

}

Method.Source:
/// <summary>
/// Processes CSD sales order.
/// </summary>
/// <param name = "_contract">Data contract.</param>
public void process(METCreateCSDTransferOrderContract _contract)
{
    contract = _contract;

    this.init();

    this.buildProfileSalesLineMap();
    this.scheduleBatchTasks();
}

/// <summary>
/// Schedules batch tasks.
/// </summary>
private void scheduleBatchTasks()
{
    METCreateCSDTransferOrderTaskController taskController;
    METCreateCSDTransferOrderTaskContract   taskContract;
    BatchHeader                             batchHeader;
    MapEnumerator                           enumerator;
    int                                     taskScheduled;

    batchHeader = BatchHeader::construct();
    enumerator = profileSalesLine.getEnumerator() as MapEnumerator;

    while (enumerator && enumerator.moveNext())
    {
        METFulfilmentProfileId prodfileId = enumerator.currentKey();
        List salesLineList = enumerator.currentValue();

        taskController = METCreateCSDTransferOrderTaskController::construct();
        taskContract = taskController.getDataContractObject() as METCreateCSDTransferOrderTaskContract;

        taskContract.parmProfileId(prodfileId);
        taskContract.parmSalesLineList(saleslineList);

        batchHeader.addTask(taskController);

        taskScheduled++;
    }

    if (taskScheduled > 0)
    {
        batchHeader.parmCaption(strFmt("@MET:ExtractServiceBy", "@MET:CreateCSDTransferOrder", curUserId()));
        batchHeader.save();
    }
}

/// <summary>
/// Initializes variables.
/// </summary>
private void init()
{
    csdSalesOrderList = contract.parmCSDSalesOrderList();
    csdWarehouse      = contract.parmCSDWarehouse();
    profileSalesLine  = new Map(Types::String, Types::Class);
}

/// <summary>
/// Builds ProfileSalesLine  map.
/// </summary>
private void buildProfileSalesLineMap()
{
    METFulfilmentProfile     profile;
    METFulfilmentLegalEntity legalEntity;

    while select profile
        where profile.InventLocationId == csdWarehouse
        exists join legalEntity
            where legalEntity.ProfileId == profile.ProfileId
            &&    legalEntity.LegalEntity == curExt()
    {
        this.buildMapFromQuery(profile);
    }
}

/// <summary>
/// Builds map from query.
/// </summary>
/// <param name = "_profile">
/// METFulfilmentProfile record.
/// </param>
private void buildMapFromQuery(METFulfilmentProfile _profile)
{
    QueryBuildDataSource qbds;
    QueryRun             queryRun;
    Query                query;

    query = new Query(_profile.ConditionQueryPacked);
    qbds = query.dataSourceTable(tableNum(SalesLine));

    for (int i = 1; i <= conLen(csdSalesOrderList); i++)
    {
        SalesId salesId = conPeek(csdSalesOrderList, i);
        QueryBuildRange qbr = qbds.addRange(fieldNum(SalesLine, SalesId));

        qbr.value(queryValue(salesId));
    }

    queryRun = new QueryRun(query);

    while (queryRun.next())
    {
        SalesLine salesLine = queryRun.get(tableNum(SalesLine));

        this.addToMap(_profile.ProfileId, salesLine);
    }
}

/// <summary>
/// Adds to map.
/// </summary>
/// <param name = "_profileId">Profile Id.</param>
/// <param name = "_salesLine">SalesLine.</param>
private void addToMap(METFulfilmentProfileId _profileId, SalesLine _salesLine)
{
    List salesLineList;

    if (!profileSalesLine.exists(_profileId))
    {
        salesLineList = new List(Types::String);
    }
    else
    {
        salesLineList = profileSalesLine.lookup(_profileId);
    }

    salesLineList.addEnd(_salesLine.InventTransId);
    profileSalesLine.insert(_profileId, salesLineList);
}
